package com.sitionix.forgeai.application.agentproxy;
import com.sitionix.forgeai.domain.model.agentproxy.*; import com.sitionix.forgeai.domain.port.ForgeAgentClient; import com.sitionix.forgeai.domain.usecase.ManageAgentProjectServices; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AgentProjectServicesUseCase implements ManageAgentProjectServices { private final ForgeAgentClient client; public List<AgentProjectService> list(UUID p){return client.listProjectServices(p);} public AgentProjectService create(UUID p,SaveAgentProjectServiceCommand c){return client.createProjectService(p,c);} public AgentProjectService get(UUID p,UUID s){return client.getProjectService(p,s);} public AgentProjectService update(UUID p,UUID s,SaveAgentProjectServiceCommand c){return client.updateProjectService(p,s,c);} public void delete(UUID p,UUID s){client.deleteProjectService(p,s);} public AgentServiceRuntime runtime(UUID p,UUID s){return client.getProjectServiceRuntime(p,s);} public List<AgentLogSource> logs(UUID p,UUID s){return client.listProjectServiceLogSources(p,s);} }
